"""Train original multi-engine proposals. No real recordings / downloaded weights.
Requires numpy and scikit-learn. Run GenerateMultiDataset first.
The holdout is grouped by complete rows; a fixed one-in-seven partition is unseen.
"""
import os
os.environ['OPENBLAS_NUM_THREADS']='1';os.environ['OMP_NUM_THREADS']='1'
from pathlib import Path
import sys,json
import numpy as np
from sklearn.neural_network import MLPRegressor,MLPClassifier
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import mean_squared_error,accuracy_score,confusion_matrix
root=Path(__file__).resolve().parents[1]
a=np.fromfile(sys.argv[1],dtype=np.float32).reshape(-1,186);x,y,label=a[:,:155],a[:,155:185],a[:,185].astype(int)
train=np.arange(len(a))%7!=0;scale=StandardScaler().fit(x[train]);z=scale.transform(x);onehot=np.eye(4,dtype=np.float32)[label];joined=np.concatenate([z,onehot],axis=1)
reg=MLPRegressor(hidden_layer_sizes=(80,48),max_iter=180,early_stopping=True,n_iter_no_change=14,validation_fraction=.12,batch_size=128,alpha=.02,random_state=410,learning_rate_init=.001).fit(joined[train],y[train])
clf=MLPClassifier(hidden_layer_sizes=(48,),max_iter=140,early_stopping=True,n_iter_no_change=12,validation_fraction=.12,batch_size=128,alpha=.05,random_state=411).fit(z[train],label[train])
pred=np.clip(reg.predict(joined[~train]),0,1);classified=clf.predict(z[~train]);report={'model':'NovaSeed Multi 1','rows':len(a),'training_rows':int(train.sum()),'held_out_rows':int((~train).sum()),'engines':['FM/subtractive','Procedural wavetable','Plucked waveguide','Blown resonator waveguide'],'training_source':'Original procedural audio only. No real instrument recordings. No pretrained external model.','regression_architecture':[159,80,48,30],'classifier_architecture':[155,48,4],'iterations':[reg.n_iter_,clf.n_iter_],'regressor_max_iter':180,'regressor_converged_before_limit':reg.n_iter_<180,'held_out_parameter_mse':float(mean_squared_error(y[~train],pred)),'engine_accuracy_synthetic':float(accuracy_score(label[~train],classified)),'confusion_matrix':confusion_matrix(label[~train],classified).tolist(),'limitations':'Synthetic holdout metrics are not real-instrument recognition or perceptual fidelity. Proposed parameters and engine priority must be evaluated by rendering. Physical models are simplified.'}
def arr(name,v):
 v=np.asarray(v).ravel();return 'inline constexpr float '+name+'['+str(len(v))+']={\n'+',\n'.join(','.join(f'{float(t):.8e}f' for t in v[i:i+8]) for i in range(0,len(v),8))+'\n};\n'
s='#pragma once\n// Generated by TrainMultiModel.py from original procedural audio. GPL-3.0-or-later.\nnamespace nova::multi_weights {\n'+arr('mean',scale.mean_)+arr('scale',scale.scale_)
for prefix,model in [('r',reg),('c',clf)]:
 for i,(w,b) in enumerate(zip(model.coefs_,model.intercepts_)):s+=arr(prefix+'w'+str(i),w.T)+arr(prefix+'b'+str(i),b)
s+='}\n';(root/'Source/MultiNeuralWeights.h').write_text(s);(root/'Training/MultiModelReport.json').write_text(json.dumps(report,indent=2)+'\n');a[~train][:96].astype(np.float32).tofile(root/'Training/MultiHoldout.bin');print(json.dumps(report,indent=2),flush=True)
